#include <unity.h>
#include "upload_csv.h"
#include "upload_protocol.h"
namespace {
StaticJsonDocument<4096> doc;
char row[tunnel::upload::CsvRowCapacity];
const char* wifi=R"({"schema":1,"capture_mode":"wardriver","type":"wifi","utc":"2026-11-02T14:32:10Z","gps":{"valid":true,"age_ms":500,"lat":41.25,"lon":-72.5,"alt_m":45,"hdop":1.2},"wifi":{"bssid":"aa:bb:cc:dd:ee:ff","ssid":"Example AP","security":"[WPA2]","rssi":-52,"channel":6,"frequency_mhz":2437}})";
void reset(){doc.clear();TEST_ASSERT_FALSE(deserializeJson(doc,wifi));}
size_t convert(){return tunnel::upload::csvRow(doc.as<JsonVariantConst>(),row,sizeof(row));}
void accepted_ap(){reset();TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_EQUAL_STRING("\"AA:BB:CC:DD:EE:FF\",\"Example AP\",\"[WPA2]\",\"2026-11-02 14:32:10\",\"6\",\"2437\",\"-52\",\"41.25\",\"-72.5\",\"45\",\"\",\"\",\"\",\"WIFI\"\n",row);}
void reject_non_inventory(){reset();doc["capture_mode"]="recon";TEST_ASSERT_EQUAL(0,convert());reset();doc["type"]="lora";TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi"]["wifi_frame"]=true;TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi"]["raw_frame_hex"]="00";TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi_frame"]=nullptr;TEST_ASSERT_EQUAL(0,convert());}
void fix_is_required(){reset();doc["gps"]["valid"]=false;TEST_ASSERT_EQUAL(0,convert());reset();doc["gps"]["age_ms"]=10001;TEST_ASSERT_EQUAL(0,convert());reset();doc["gps"]["lat"]=true;TEST_ASSERT_EQUAL(0,convert());reset();doc["gps"]["lon"]=181;TEST_ASSERT_EQUAL(0,convert());reset();doc["gps"].remove("age_ms");TEST_ASSERT_EQUAL(0,convert());}
void strict_radio_metadata(){reset();doc["wifi"]["frequency_mhz"]=2438;TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi"]["channel"]=true;TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi"]["bssid"]="00:11:22:33:44:xx";TEST_ASSERT_EQUAL(0,convert());reset();doc["wifi"]["rssi"]=-128;TEST_ASSERT_EQUAL(0,convert());}
void csv_escaping(){reset();doc["wifi"]["ssid"]="a,\"b\"\r\nc";TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"\"a,\"\"b\"\"\\r\\nc\""));}
void exact_ssid_recovery(){reset();doc["wifi"]["ssid_sanitized"]=true;doc["wifi"]["ssid_hex"]="636166c3a9";TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"caf\xc3\xa9"));doc["wifi"]["ssid_hex"]="c080";TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"FF\",\"\",\"[WPA2]"));doc["wifi"]["ssid_hex"]="610062";TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"FF\",\"\",\"[WPA2]"));}
void public_ble_only(){reset();doc["type"]="ble";auto ble=doc.createNestedObject("ble");ble["address"]="aa:bb:cc:dd:ee:ff";ble["name"]="Beacon";ble["rssi"]=-70;ble["address_type"]="random";TEST_ASSERT_EQUAL(0,convert());ble["address_type"]="public";ble["manufacturer_id"]=76;TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"\"76\",\"BLE\""));ble["name_sanitized"]=true;TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NULL(strstr(row,"Beacon"));ble["manufacturer_id"]=65536;TEST_ASSERT_EQUAL(0,convert());}
void valid_calendar_utc(){char stamp[20];TEST_ASSERT_TRUE(tunnel::upload::nativeUtc("2024-02-29T23:59:59Z",stamp));TEST_ASSERT_FALSE(tunnel::upload::nativeUtc("2026-02-29T23:59:59Z",stamp));TEST_ASSERT_FALSE(tunnel::upload::nativeUtc("2026-11-02T24:00:00Z",stamp));TEST_ASSERT_FALSE(tunnel::upload::nativeUtc("2026-11-02 12:00:00",stamp));reset();doc["utc"]="not time";TEST_ASSERT_EQUAL(0,convert());}
void no_overflow_or_fake_accuracy(){reset();char tiny[12];TEST_ASSERT_EQUAL(0,tunnel::upload::csvRow(doc.as<JsonVariantConst>(),tiny,sizeof(tiny)));TEST_ASSERT_EQUAL(0,tiny[11]);doc["gps"]["accuracy_m"]=3.5;TEST_ASSERT_GREATER_THAN(0,convert());TEST_ASSERT_NOT_NULL(strstr(row,"\"45\",\"3.5\""));}
void receipt_truth(){using namespace tunnel::upload;doc.clear();doc["accepted"]=true;TEST_ASSERT_EQUAL(int(Receipt::Accepted),int(receipt(1,200,doc.as<JsonVariantConst>())));TEST_ASSERT_EQUAL(int(Receipt::Rejected),int(receipt(1,409,doc.as<JsonVariantConst>())));doc["accepted"]=false;doc["item_count"]=4;TEST_ASSERT_EQUAL(int(Receipt::Rejected),int(receipt(1,200,doc.as<JsonVariantConst>())));doc["duplicate"]=true;TEST_ASSERT_EQUAL(int(Receipt::Accepted),int(receipt(1,200,doc.as<JsonVariantConst>())));doc.clear();doc["success"]=true;TEST_ASSERT_EQUAL(int(Receipt::Accepted),int(receipt(0,200,doc.as<JsonVariantConst>())));TEST_ASSERT_EQUAL(int(Receipt::Authentication),int(receipt(0,401,doc.as<JsonVariantConst>())));TEST_ASSERT_EQUAL(int(Receipt::Retryable),int(receipt(0,503,doc.as<JsonVariantConst>())));TEST_ASSERT_EQUAL(int(Receipt::Rejected),int(receipt(0,302,doc.as<JsonVariantConst>())));}
void asynchronous_job_receipts(){using namespace tunnel::upload;doc.clear();doc["job_id"]="job_123-abc";TEST_ASSERT_EQUAL(int(Receipt::JobPending),int(receipt(2,202,doc.as<JsonVariantConst>())));doc["job_id"]="../secret";TEST_ASSERT_EQUAL(int(Receipt::Rejected),int(receipt(2,202,doc.as<JsonVariantConst>())));doc.clear();doc["status"]="processing";TEST_ASSERT_EQUAL(int(Receipt::JobPending),int(receipt(2,200,doc.as<JsonVariantConst>(),true)));doc["status"]="done";TEST_ASSERT_EQUAL(int(Receipt::Accepted),int(receipt(2,200,doc.as<JsonVariantConst>(),true)));doc["status"]="failed";TEST_ASSERT_EQUAL(int(Receipt::JobFailed),int(receipt(2,200,doc.as<JsonVariantConst>(),true)));}
void checkpoint_restart_policy(){using namespace tunnel::upload;TEST_ASSERT_FALSE(checkpointMaySend("accepted",false));TEST_ASSERT_FALSE(checkpointMaySend("accepted",true));TEST_ASSERT_FALSE(checkpointMaySend("job",true));TEST_ASSERT_FALSE(checkpointMaySend("sending",false));TEST_ASSERT_FALSE(checkpointMaySend("uncertain",false));TEST_ASSERT_TRUE(checkpointMaySend("uncertain",true));TEST_ASSERT_FALSE(checkpointMaySend("rejected",false));TEST_ASSERT_TRUE(checkpointMaySend("rejected",true));TEST_ASSERT_TRUE(checkpointMaySend("retry",false));TEST_ASSERT_EQUAL(30000,retryDelay(1));TEST_ASSERT_EQUAL(120000,retryDelay(2));TEST_ASSERT_EQUAL(600000,retryDelay(3));}
void explicit_modes_and_synthetic(){reset();doc["capture_mode"]=nullptr;TEST_ASSERT_EQUAL(0,convert());doc["capture_mode"]=42;TEST_ASSERT_EQUAL(0,convert());doc.remove("capture_mode");TEST_ASSERT_GREATER_THAN(0,convert());doc["synthetic"]=true;TEST_ASSERT_EQUAL(0,convert());}
void numeric_job_id(){char job[81];doc.clear();doc["job_id"]=42;TEST_ASSERT_TRUE(tunnel::upload::normalizeJobId(doc["job_id"],job,sizeof(job)));TEST_ASSERT_EQUAL_STRING("42",job);TEST_ASSERT_EQUAL(int(tunnel::upload::Receipt::JobPending),int(tunnel::upload::receipt(2,202,doc.as<JsonVariantConst>())));doc["job_id"]=true;TEST_ASSERT_FALSE(tunnel::upload::normalizeJobId(doc["job_id"],job,sizeof(job)));doc["job_id"]=0;TEST_ASSERT_FALSE(tunnel::upload::normalizeJobId(doc["job_id"],job,sizeof(job)));doc["job_id"]=-1;TEST_ASSERT_FALSE(tunnel::upload::normalizeJobId(doc["job_id"],job,sizeof(job)));}
}
void setUp(){}
void tearDown(){}
int main(){UNITY_BEGIN();RUN_TEST(accepted_ap);RUN_TEST(reject_non_inventory);RUN_TEST(fix_is_required);RUN_TEST(strict_radio_metadata);RUN_TEST(csv_escaping);RUN_TEST(exact_ssid_recovery);RUN_TEST(public_ble_only);RUN_TEST(valid_calendar_utc);RUN_TEST(no_overflow_or_fake_accuracy);RUN_TEST(receipt_truth);RUN_TEST(asynchronous_job_receipts);RUN_TEST(checkpoint_restart_policy);RUN_TEST(explicit_modes_and_synthetic);RUN_TEST(numeric_job_id);return UNITY_END();}
